class Visual final : public Scene {
  struct Star { float radius, angle, lift, drift; int group; };
  std::vector<Star> stars;
  float turn = 0, breath = 0;
 public:
  void reset(uint32_t seed) override {
    Random rng(seed); stars.clear(); stars.reserve(1500); turn=0; breath=0;
    for(int i=0;i<1500;i++) {
      float r=std::sqrt(rng.unit()); int arm=i%4;
      stars.push_back({r, float(arm*pi/2)+r*5.8f+(rng.unit()-.5f)*(.25f+r*.8f),
        (rng.unit()-.5f)*(.018f+r*.035f), .7f+rng.unit()*.6f, i%9});
    }
  }
  void update(const Frame& f) override {
    turn += float(f.delta)*f.speed*.06f;
    float target=f.music.energy;
    breath += (target-breath)*float(1-std::exp(-f.delta*3));
  }
  void render(const Frame& f, Canvas& c) const override {
    Paint sky=Paint::radial({f.width*.5f,f.height*.47f},f.height*.75f,
      {Color::argb(0xff151031),Color::argb(0xff03040d)});
    c.rect({0,0,f.width,f.height},sky);
    c.save(); c.translate(f.width*.5f,f.height*.48f); c.rotate(-.38f);
    float scale=std::min(f.width*.62f,f.height*.42f)*(1+breath*.045f);
    Paint haze=Paint::radial({0,0},scale*.8f,{Color{.24f,.1f,.5f,.2f},Color{.08f,.02f,.3f,0}});
    haze.blend=Blend::plus; c.rect({-scale,-scale,scale*2,scale*2},haze);
    for(int group=0;group<9;group++) {
      std::vector<Vec2> batch;batch.reserve(170);
      for(const auto& s:stars) if(s.group==group) {
        float a=s.angle+turn*s.drift;
        batch.push_back({std::cos(a)*s.radius*scale,
          std::sin(a)*s.radius*scale*.49f+s.lift*scale});
      }
      Paint p;p.blend=Blend::plus;
      p.color=group%3==0?Color{.58f,.69f,1,.65f}:group%3==1?Color{1,.67f,.48f,.6f}:Color{.9f,.72f,1,.72f};
      c.points(batch,.55f+(group/3)*.5f,p);
    }
    Paint core=Paint::radial({0,0},scale*.28f,{Color{1,.87f,.68f,.92f},Color{.65f,.34f,.75f,.22f},Color{.2f,.1f,.6f,0}},{0,.22f,1});
    core.blend=Blend::screen;c.circle({0,0},scale*.28f,core);c.restore();
  }
};

class Visual final : public Scene {
  struct Particle { float x,y,velocity,phase; };
  std::vector<Particle> particles;
  float impulse=0;
 public:
  void reset(uint32_t seed) override {
    Random r(seed);particles.clear();impulse=0;
    for(int i=0;i<240;i++)particles.push_back({r.unit(),r.unit(),.02f+r.unit()*.03f,r.unit()*6.28f});
  }
  void update(const Frame& f) override {
    for(const auto& event:f.music.events[0])impulse=std::max(impulse,event.strength);
    impulse*=float(std::exp(-f.delta*2.2));
    for(auto& p:particles){p.y-=p.velocity*float(f.delta)*f.speed*(1+impulse*3);
      if(p.y<-.03f)p.y+=1.06f;p.phase+=float(f.delta)*.3f;}
  }
  void render(const Frame& f, Canvas& c) const override {
    for(int group=0;group<4;group++){
      std::vector<Vec2> points;
      for(size_t i=group;i<particles.size();i+=4){const auto& p=particles[i];
        points.push_back({(p.x+std::sin(p.phase+p.y*3)*.02f)*f.width,p.y*f.height});}
      Paint paint;paint.blend=Blend::plus;paint.color={1,.65f+group*.05f,.25f+group*.12f,.35f+group*.16f};
      c.points(points,.8f+group*.45f+impulse*.4f,paint);
    }
  }
};

class Visual final : public Scene {
  struct Star { float x, y, z0, cycle; };
  std::vector<Star> stars;
 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    stars.clear(); stars.reserve(621);
    for (int i = 0; i < 621; i++) {
      Star s;
      s.x = (rng.unit() - 0.5f) * 2.2f;
      s.y = (rng.unit() - 0.5f) * 2.2f;
      s.z0 = rng.unit() * 2.2f + 0.05f;
      s.cycle = 2.2f + 1.2f;
      stars.push_back(s);
    }
  }
  void update(const Frame& f) override { (void)f; }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float cx = w * 0.5f, cy = h * 0.5f;
    float t = float(f.time) * f.speed;
    float rate = (1.1f + std::sin(t * 0.25f) * 0.55f) * (1.0f + f.music.energy * 0.8f);
    if (f.reducedMotion) rate *= 0.4f;
    float travel = t * rate * 0.96f;
    float boost = (0.7f + 0.5f * f.music.energy + 0.4f * f.music.bass) * f.intensity;
    Paint bg; bg.color = Color::argb(0xff02020c);
    c.rect({0, 0, w, h}, bg);
    Path lanes[3];
    std::vector<Vec2> heads[3];
    for (int i = 0; i < 3; i++) heads[i].reserve(240);
    for (size_t idx = 0; idx < stars.size(); idx++) {
      const Star& s = stars[idx];
      float z = std::fmod(s.z0 - travel, s.cycle);
      if (z < 0.04f) z += s.cycle;
      float x1 = cx + (s.x / z) * 0.75f;
      float y1 = cy + (s.y / z) * 0.75f;
      if (x1 < -80 || x1 > w + 80 || y1 < -80 || y1 > h + 80) continue;
      float tail = z + 0.11f;
      int lane = int(idx % 3);
      lanes[lane].moveTo(cx + (s.x / tail) * 0.75f, cy + (s.y / tail) * 0.75f);
      lanes[lane].lineTo(x1, y1);
      heads[lane].push_back({x1, y1});
    }
    for (int lane = 0; lane < 3; lane++) {
      Paint p; p.blend = Blend::plus;
      if (lane == 0) { p.color = {1, 1, 1, 0.9f * boost}; p.strokeWidth = 1.7f; }
      else if (lane == 1) { p.color = {0.749f, 0.894f, 1, 0.55f * boost}; p.strokeWidth = 1.1f; }
      else { p.color = {1, 0.839f, 0.941f, 0.55f * boost}; p.strokeWidth = 1.1f; }
      p.strokeCap = 1; p.strokeJoin = 1;
      c.path(lanes[lane], p);
      if (!heads[lane].empty()) {
        Paint hp; hp.blend = Blend::plus;
        hp.color = {1, 1, 1, 0.85f * boost};
        c.points(heads[lane], 0.85f, hp);
      }
    }
    Paint glow = Paint::radial({cx, cy}, std::min(w, h) * 0.45f,
      {{0.549f, 0.745f, 1, 0.28f * boost}, {0, 0, 0, 0}});
    glow.blend = Blend::plus;
    c.rect({0, 0, w, h}, glow);
  }
};

class Visual final : public Scene {
  struct Part { float r, a0, spd, w; };
  struct Star { float x, y, m; };
  std::vector<Part> parts;
  std::vector<Star> stars;
 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    parts.clear(); stars.clear();
    int np = 620;
    parts.reserve(np);
    for (int i = 0; i < np; i++) {
      Part p;
      float u = rng.unit();
      p.r = 1.55f + std::pow(u, 0.62f) * 3.6f;
      p.a0 = rng.unit() * 6.2831853f;
      // Kepler: la velocidad angular cae con r^1.5 => rotación diferencial real.
      p.spd = 1.0f / (p.r * std::sqrt(p.r));
      p.w = 0.5f + rng.unit() * 2.2f;
      parts.push_back(p);
    }
    stars.reserve(320);
    for (int i = 0; i < 320; i++) {
      Star s; s.x = rng.unit(); s.y = rng.unit(); s.m = rng.unit();
      stars.push_back(s);
    }
  }
  void update(const Frame& f) override { (void)f; }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = float(f.time) * f.speed;
    float cx = w * 0.5f, cy = h * 0.5f;
    float rs = std::min(w, h) * 0.13f;
    float yaw = std::sin(t * 0.09f) * 0.22f * (1.0f + f.music.energy * 0.3f);
    float squash = 0.24f + std::cos(t * 0.07f) * 0.14f;
    float boost = (0.85f + 0.35f * f.music.energy) * f.intensity;
    float spin = t * 0.06f * (f.reducedMotion ? 0.3f : 1.0f);
    Paint bg; bg.color = Color::argb(0xff030308);
    c.rect({0, 0, w, h}, bg);

    // ── Estrellas con deflexión gravitatoria ──
    std::vector<Vec2> field;
    field.reserve(stars.size());
    for (const auto& s : stars) {
      float bx = s.x * w, by = s.y * h;
      float dx = bx - cx, dy = by - cy;
      float d = std::sqrt(dx * dx + dy * dy) + 1.0f;
      if (d < rs * 1.25f) continue; // devoradas por la sombra
      float k = 1.0f + (rs * rs * 5.2f) / (d * d);
      field.push_back({cx + dx * k, cy + dy * k});
    }
    Paint sp; sp.blend = Blend::plus;
    sp.color = {0.863f, 0.910f, 1, 0.69f * boost};
    c.points(field, 1.1f, sp);

    const uint32_t ramp[4] = {0xffc9432a, 0xffff8f4a, 0xffffd166, 0xfffff3d0};

    // Disco: cuatro bandas de calor, dos pasadas para el orden.
    for (int pass = 0; pass < 2; pass++) {
      for (int b = 0; b < 4; b++) {
        Path disk;
        for (const auto& p : parts) {
          float heat = 1.0f - (p.r - 1.55f) / 3.6f;
          if (heat < 0.0f) heat = 0.0f; if (heat > 1.0f) heat = 1.0f;
          if (int(heat * 3.999f) != b) continue;
          float rad = p.r * rs;
          float a = p.a0 + spin * p.spd + yaw;
          float sa = std::sin(a);
          if ((sa < 0.0f ? 0 : 1) != pass) continue;
          float x = cx + std::cos(a) * rad;
          float y = cy + sa * rad * squash;
          float len = p.w * (2.2f + heat * 6.0f);
          disk.moveTo(x + std::sin(a) * len, y - std::cos(a) * squash * len);
          disk.lineTo(x, y);
        }
        Color cc = Color::argb(ramp[b]);
        Paint dp; dp.blend = Blend::plus;
        dp.color = {cc.r, cc.g, cc.b, (0.10f + float(b) * 0.14f) * boost};
        dp.strokeWidth = 0.7f + float(b) * 0.5f;
        dp.strokeCap = 1; dp.strokeJoin = 1;
        c.path(disk, dp);
      }
      if (pass == 0) {
        // ── Anillo fotónico ──
        float ringR = rs * 1.34f;
        Paint rp; rp.blend = Blend::plus;
        for (int i = 3; i >= 1; i--) {
          rp.color = {1, 0.819f, 0.400f, 0.051f * boost};
          rp.strokeWidth = rs * 0.16f * float(i);
          c.circle({cx, cy}, ringR * (1.0f + float(i) * 0.07f), rp);
        }
        Paint crisp; crisp.blend = Blend::plus;
        crisp.color = {1, 0.941f, 0.824f, 0.949f * boost};
        crisp.strokeWidth = std::max(1.0f, rs * 0.045f);
        c.circle({cx, cy}, ringR, crisp);
        // ── Sombra del horizonte ──
        Paint shadow; shadow.color = {0, 0, 0, 1};
        c.circle({cx, cy}, rs, shadow);
      }
    }

    // ── Arco de Einstein: imagen lensada del disco sobre el horizonte ──
    Path arc;
    const int steps = 48;
    for (int i = 0; i <= steps; i++) {
      float a = 3.14159265f * 1.06f + float(i) / float(steps) * 3.14159265f * 0.88f;
      float x = cx + std::cos(a) * rs * 1.16f;
      float y = cy + std::sin(a) * rs * 1.16f;
      if (i == 0) arc.moveTo(x, y); else arc.lineTo(x, y);
    }
    Paint ap; ap.blend = Blend::plus;
    ap.color = {1, 0.722f, 0.361f, 0.502f * boost};
    ap.strokeWidth = rs * 0.2f; ap.strokeCap = 1; ap.strokeJoin = 1;
    c.path(arc, ap);

    // Resplandor global.
    Paint glow = Paint::radial({cx, cy}, rs * 6.5f,
      {{1, 0.667f, 0.314f, 0.141f * boost}, {0.627f, 0.314f, 1, 0.051f * boost}, {0, 0, 0, 0}},
      {0.0f, 0.4f, 1.0f});
    glow.blend = Blend::plus;
    c.rect({0, 0, w, h}, glow);
  }
};

class Visual final : public Scene {
  std::vector<float> ridge;
  float pulse = 0;
  static float vhash(int x, int y) {
    uint32_t h = uint32_t(x) * 374761393u + uint32_t(y) * 668265263u;
    h = (h ^ (h >> 13)) * 1274126177u; h ^= h >> 16;
    return float(h & 0xffffu) / 65535.0f;
  }
  static float vnoise(float x, float y) {
    int xi = int(std::floor(x)), yi = int(std::floor(y));
    float xf = x - float(xi), yf = y - float(yi);
    float u = xf * xf * (3.0f - 2.0f * xf), v = yf * yf * (3.0f - 2.0f * yf);
    float a = vhash(xi, yi), b = vhash(xi + 1, yi);
    float c = vhash(xi, yi + 1), d = vhash(xi + 1, yi + 1);
    return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
  }
 public:
  void reset(uint32_t seed) override {
    (void)seed; ridge.clear(); pulse = 0;
  }
  void update(const Frame& f) override {
    if (ridge.size() != 30) {
      ridge.resize(30);
      for (int i = 0; i < 30; i++)
        ridge[i] = (vnoise(float(i) * 0.4f, 1.0f) * 0.5f + vnoise(float(i) * 0.9f, 7.0f) * 0.5f);
    }
    for (const auto& band : f.music.events)
      for (const auto& e : band) pulse += e.strength;
    pulse *= float(std::exp(-f.delta * 4.0));
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = float(f.time) * f.speed;
    float hz = h * 0.56f;
    float glowBoost = (0.7f + 0.6f * f.music.bass + 0.8f * pulse) * f.intensity;
    Paint sky = Paint::linear({0, 0}, {0, hz},
      {Color::argb(0xff160034), Color::argb(0xff4a0a6b), Color::argb(0xffff4d78)}, {0, 0.55f, 1.0f});
    c.rect({0, 0, w, hz}, sky);
    float sr = std::min(w, h) * 0.22f;
    float sunCx = w * 0.5f, sunCy = hz - sr * 0.15f;
    c.save();
    Path sunClip; sunClip.circle({sunCx, sunCy}, sr);
    c.clip(sunClip);
    Paint sun = Paint::linear({0, hz - sr * 1.3f}, {0, hz + 4.0f},
      {Color::argb(0xfffff36b), Color::argb(0xffff8a3d), Color::argb(0xffff2e9a)}, {0, 0.45f, 1.0f});
    c.rect({sunCx - sr, hz - sr * 1.3f, sr * 2.0f, sr * 2.0f}, sun);
    Paint bar; bar.color = Color::argb(0xff160034);
    float lane = sr * 0.14f;
    float off = std::fmod(t * 14.0f, lane);
    for (int i = 0; i < 9; i++) {
      float y = hz - sr * 0.9f + float(i) * lane + off;
      c.rect({sunCx - sr, y, sr * 2.0f, float(i) * 0.55f + 1.5f}, bar);
    }
    c.restore();
    Path mtn; mtn.moveTo(0, hz);
    for (int i = 0; i < 30; i++)
      mtn.lineTo(float(i) / 29.0f * w, hz - ridge[i] * h * 0.16f);
    mtn.lineTo(w, hz); mtn.close();
    Paint mfill; mfill.color = Color::argb(0xff0d0020);
    c.path(mtn, mfill);
    Paint mstroke; mstroke.color = {1, 0.435f, 0.847f, 0.9f * f.intensity};
    mstroke.strokeWidth = 1.0f;
    c.path(mtn, mstroke);
    Paint floor = Paint::linear({0, hz}, {0, h},
      {Color::argb(0xff12002b), Color::argb(0xff2a004d)});
    c.rect({0, hz, w, h - hz}, floor);
    Path grid;
    for (int i = -9; i <= 9; i++) {
      grid.moveTo(w * 0.5f, hz);
      grid.lineTo(w * 0.5f + float(i) * w * 0.34f, h);
    }
    float speed = std::fmod(t * 0.55f, 1.0f);
    for (int i = 0; i < 16; i++) {
      float k = (float(i) + speed) / 16.0f;
      float y = hz + (h - hz) * k * k * 1.02f;
      if (y > h) continue;
      grid.moveTo(0, y); grid.lineTo(w, y);
    }
    Paint gp; gp.color = {0, 1, 0.965f, 0.75f * f.intensity};
    gp.strokeWidth = 1.1f;
    c.path(grid, gp);
    Paint hg = Paint::linear({0, hz - 26.0f}, {0, hz + 26.0f},
      {{1, 0.18f, 0.604f, 0}, {1, 0.47f, 0.784f, 0.35f * glowBoost}, {0, 1, 0.965f, 0}}, {0, 0.5f, 1.0f});
    hg.blend = Blend::plus;
    c.rect({0, hz - 26.0f, w, 52.0f}, hg);
  }
};

class Visual final : public Scene {
  std::vector<Vec2> buckets[6];
  float step = 12.0f, cols = 0, rows = 0, lastW = 0, lastH = 0, lastDetail = -1.0f;
  void build(float w, float h, float detail) {
    step = std::max(9.0f, std::min(w, h) / (18.0f + 16.0f * detail));
    cols = std::ceil(w / step) + 1.0f;
    rows = std::ceil(h / step) + 1.0f;
  }
 public:
  void reset(uint32_t seed) override {
    (void)seed;
    for (int i = 0; i < 6; i++) buckets[i].clear();
    lastW = 0; lastH = 0; lastDetail = -1.0f;
  }
  void update(const Frame& f) override {
    float w = f.width, h = f.height;
    float t = float(f.time) * f.speed;
    if (w != lastW || h != lastH || f.detail != lastDetail) {
      build(w, h, f.detail);
      lastW = w; lastH = h; lastDetail = f.detail;
    }
    float amp = 1.0f + f.music.bass * 0.6f;
    float s1x = w * (0.5f + std::sin(t * 0.35f) * 0.32f);
    float s1y = h * (0.35f + std::sin(t * 0.27f + 1.0f) * 0.2f);
    float s2x = w * (0.5f + std::sin(t * 0.31f + 2.4f) * 0.34f);
    float s2y = h * (0.68f + std::sin(t * 0.23f + 3.0f) * 0.2f);
    for (int i = 0; i < 6; i++) buckets[i].clear();
    for (int j = 0; j < int(rows); j++) {
      float y = float(j) * step;
      for (int i = 0; i < int(cols); i++) {
        float x = float(i) * step;
        float dx1 = x - s1x, dy1 = y - s1y;
        float dx2 = x - s2x, dy2 = y - s2y;
        float d1 = std::sqrt(dx1 * dx1 + dy1 * dy1);
        float d2 = std::sqrt(dx2 * dx2 + dy2 * dy2);
        float v = std::sin(d1 * 0.085f - t * 2.4f) + std::sin(d2 * 0.07f - t * 1.9f);
        float k = (v + 2.0f) * 0.25f;
        int b = int(k * 5.99f);
        if (b < 0) b = 0; if (b > 5) b = 5;
        buckets[b].push_back({x, y + (k - 0.5f) * step * 0.55f * amp});
      }
    }
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    Paint bg; bg.color = Color::argb(0xff03071c);
    c.rect({0, 0, w, h}, bg);
    const uint32_t pal[6] = {0xff0a1b4a, 0xff123a8a, 0xff1f6fd0,
      0xff35b3f0, 0xff7fe9ff, 0xffd9fbff};
    for (int b = 0; b < 6; b++) {
      if (buckets[b].empty()) continue;
      Color cc = Color::argb(pal[b]);
      Paint p; p.blend = Blend::plus;
      p.color = {cc.r, cc.g, cc.b, (0.55f + 0.45f * f.music.energy) * f.intensity};
      c.points(buckets[b], (1.0f + float(b) / 5.0f * step * 0.42f) * 0.5f, p);
    }
  }
};

class Visual final : public Scene {
  static constexpr int cols = 46;
  static constexpr int rows = 46;
 public:
  void reset(uint32_t seed) override { (void)seed; }
  void update(const Frame& f) override { (void)f; }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = float(f.time) * f.speed;
    float horizon = h * 0.34f;
    Paint sky = Paint::linear({0, 0}, {0, h},
      {Color::argb(0xff070a10), Color::argb(0xff101a18),
       Color::argb(0xff05070a), Color::argb(0xff04050a)}, {0, 0.33f, 0.36f, 1.0f});
    c.rect({0, 0, w, h}, sky);

    float lean = std::sin(t * 0.21f) * 0.16f * (1.0f + f.music.bass * 0.5f);
    float boost = (0.8f + 0.35f * f.music.energy) * f.intensity;
    float sunX = w * (0.5f + lean);
    Paint sunPaint = Paint::radial({sunX, horizon}, w * 0.5f,
      {{0.776f, 0.910f, 0.310f, 0.42f * boost}, {0.471f, 0.784f, 0.471f, 0.12f * boost},
       {0, 0, 0, 0}}, {0.0f, 0.25f, 1.0f});
    sunPaint.blend = Blend::plus;
    c.rect({0, 0, w, h}, sunPaint);

    float scroll = t * 6.2831853f * 0.55f;
    float f0 = h * 0.95f;
    const float camH = 2.6f, span = 9.0f;
    Path row;
    Paint line;
    line.strokeCap = 1; line.strokeJoin = 1;
    // De lejos a cerca: el trazo más próximo tapa al lejano, sin z-buffer.
    for (int j = rows; j >= 0; j--) {
      float zt = float(j) / float(rows);
      float z = 0.75f * std::pow(26.0f, zt);
      float k = f0 / z;
      row = Path();
      for (int i = 0; i <= cols; i++) {
        float xt = float(i) / float(cols) - 0.5f;
        float x = xt * span * (1.0f + z * 0.35f) + lean * z * 0.6f;
        float hgt = noise3(x * 0.42f, z * 0.24f + scroll, 0.0f) * (0.5f + z * 0.07f);
        float px = w * 0.5f + x * k;
        float py = horizon + (camH - hgt) * k;
        if (i == 0) row.moveTo(px, py); else row.lineTo(px, py);
      }
      float a = (1.0f - zt) * 1.5f;
      if (a > 1.0f) a = 1.0f; if (a < 0.0f) a = 0.0f;
      line.strokeWidth = 0.5f + (1.0f - zt) * 1.4f;
      if (zt < 0.25f) line.color = {0.918f, 1, 0.690f, a * 0.55f * boost};
      else line.color = {0.776f, 0.910f, 0.310f, a * 0.55f * boost};
      c.path(row, line);
    }

    // Verticales cada cuatro columnas en un único Path.
    Path wires;
    for (int i = 0; i <= cols; i += 4) {
      float xt = float(i) / float(cols) - 0.5f;
      bool first = true;
      for (int j = rows; j >= 0; j -= 3) {
        float zt = float(j) / float(rows);
        float z = 0.75f * std::pow(26.0f, zt);
        float k = f0 / z;
        float x = xt * span * (1.0f + z * 0.35f) + lean * z * 0.6f;
        float hgt = noise3(x * 0.42f, z * 0.24f + scroll, 0.0f) * (0.5f + z * 0.07f);
        float px = w * 0.5f + x * k;
        float py = horizon + (camH - hgt) * k;
        if (first) { wires.moveTo(px, py); first = false; }
        else wires.lineTo(px, py);
      }
    }
    line.color = {0.471f, 0.863f, 0.627f, 0.129f * boost};
    line.strokeWidth = 0.7f;
    c.path(wires, line);
  }
  static float noise3(float x, float y, float t) {
    return std::sin(x * 0.9f + t * 0.7f) * 0.5f
      + std::sin(y * 1.1f - t * 0.5f) * 0.34f
      + std::sin((x + y) * 0.6f + t) * 0.16f;
  }
};

class Visual final : public Scene {
  struct Bld { float x, w, h; };
  struct Win { float x, y; };
  struct Layer { std::vector<Bld> blds; std::vector<Win> wins;
                 float speed, shade, depth, height; };
  std::vector<Layer> layers;
  struct Drop { float x, y, v, len; };
  std::vector<Drop> drops;
  float lastw = 0, lasth = 0, lastDetail = -1.0f;
  static float hash01(int i, int salt) {
    float s = std::sin(float(i) * 12.9898f + float(salt) * 78.233f) * 43758.5453f;
    return s - std::floor(s);
  }
  void build(float w, float h, float detail) {
    float horizon = h * 0.66f;
    layers.clear();
    for (int li = 0; li < 4; li++) {
      Layer L;
      L.depth = float(li) / 3.0f;
      L.speed = 3.0f + L.depth * 22.0f;
      int sh = 10 + int((1.0f - L.depth) * 22.0f);
      L.shade = float(sh);
      L.height = horizon * (0.32f + L.depth * 0.66f);
      int steps = int(w / 30.0f) + 6;
      if (steps > 48) steps = 48;
      // El paso de la ventana escala con la altura de la capa: en pantallas
      // grandes el número de puntos se disparaba y reventaba el presupuesto
      // de 1 MiB de comandos del motor.
      float wyStep = std::max(9.0f, L.height / 40.0f);
      // El paso horizontal sigue a la pantalla para que el skyline siempre la
      // cubra entera, tenga el ancho que tenga.
      float xStep = w / float(steps);
      for (int i = 0; i < steps; i++) {
        Bld b;
        b.x = (float(i) + hash01(i, li) * 0.6f) * xStep;
        b.w = xStep * (0.5f + hash01(i, li + 91) * 1.5f) * (0.5f + L.depth * 0.5f);
        b.h = L.height * (0.28f + hash01(i, li + 173) * 0.72f);
        L.blds.push_back(b);
        if (L.depth > 0.35f) {
          float top = L.height - b.h;
          float wxStep = std::max(7.0f, b.w / 8.0f);
          for (float wy = 6.0f; wy < b.h - 8.0f; wy += wyStep) {
            for (float wx = 3.0f; wx < b.w - 6.0f; wx += wxStep) {
              if (hash01(int(wx) * 7 + int(wy) * 13, li + 311) > 0.62f)
                L.wins.push_back({b.x + wx, top + wy});
            }
          }
        }
      }
      layers.push_back(L);
    }
    int ndrops = int(380.0f * std::min(1.0f, std::max(0.4f, detail)));
    drops.clear(); drops.reserve(ndrops);
    for (int i = 0; i < ndrops; i++)
      drops.push_back({hash01(i, 7) * w, hash01(i, 29) * h,
        520.0f + hash01(i, 53) * 620.0f, 8.0f + hash01(i, 71) * 26.0f});
  }
 public:
  void reset(uint32_t seed) override {
    (void)seed;
    layers.clear(); drops.clear();
    lastw = 0; lasth = 0; lastDetail = -1.0f;
  }
  void update(const Frame& f) override {
    if (f.width != lastw || f.height != lasth || f.detail != lastDetail) {
      build(f.width, f.height, f.detail);
      lastw = f.width; lasth = f.height; lastDetail = f.detail;
    }
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = float(f.time) * f.speed;
    float horizon = h * 0.66f;
    float boost = (0.85f + 0.3f * f.music.energy) * f.intensity;
    Paint sky = Paint::linear({0, 0}, {0, h},
      {Color::argb(0xff05060c), Color::argb(0xff131a2c), Color::argb(0xff2a1c2c),
       Color::argb(0xff0a0c14), Color::argb(0xff04050a)}, {0, 0.42f, 0.63f, 0.67f, 1.0f});
    c.rect({0, 0, w, h}, sky);

    // Rótulos de neón con parpadeo eléctrico.
    const uint32_t neon[4] = {0xffff6a55, 0xff58c7f3, 0xff3fd8a5, 0xffffd166};
    Paint add; add.blend = Blend::plus;
    for (int i = 0; i < 7; i++) {
      float ph = float(i) * 1.7f;
      float flick = 0.55f + 0.45f * std::sin(t * 44.0f + ph) * std::sin(t * 14.0f + ph * 2.0f);
      if (flick < 0.06f) flick = 0.06f;
      if (flick > 1.0f) flick = 1.0f;
      Color cc = Color::argb(neon[i % 4]);
      add.color = {cc.r, cc.g, cc.b, flick * 0.85f * boost};
      int sw = int(w) - 90; if (sw < 1) sw = 1;
      int shh = int(horizon * 0.5f); if (shh < 1) shh = 1;
      float x = float((i * 137) % sw) + 30.0f;
      float y = horizon - 40.0f - float((i * 211) % shh);
      c.rect({x, y, 8.0f + float((i * 7) % 26), 18.0f + float((i * 13) % 54)}, add);
    }

    // Ciudad en dos pasadas: normal y reflejo mojado invertido.
    for (size_t li = 0; li < layers.size(); li++) {
      const Layer& L = layers[li];
      float period = std::max(w, 1.0f);
      float off = std::fmod(t * L.speed, period);
      float alpha = 0.35f + L.depth * 0.65f;
      for (int pass = 0; pass < 2; pass++) {
        c.save();
        Path clip;
        if (pass == 0) clip.rect({0, 0, w, horizon});
        else {
          clip.rect({0, horizon, w, h - horizon});
          c.clip(clip);
          c.translate(0, horizon);
          c.scale(1, -0.42f);
          c.translate(0, -horizon);
        }
        if (pass == 0) c.clip(clip);
        for (int rep = 0; rep < 2; rep++) {
          float dx = -off + float(rep) * period;
          Path body;
          for (const auto& b : L.blds)
            body.rect({dx + b.x, L.height - b.h, b.w - 2.0f, b.h});
          Paint fill;
          fill.color = {L.shade / 255.0f, (L.shade + 3.0f) / 255.0f,
            (L.shade + 10.0f) / 255.0f, pass == 0 ? alpha : alpha * 0.2f};
          c.path(body, fill);
          if (!L.wins.empty()) {
            std::vector<Vec2> win;
            win.reserve(L.wins.size() * 2);
            for (const auto& p : L.wins) {
              win.push_back({dx + p.x, p.y});
              win.push_back({dx + p.x, p.y});
            }
            Paint wp; wp.blend = Blend::plus;
            wp.color = {1, 0.851f, 0.627f, (pass == 0 ? 0.5f : 0.1f) * alpha * boost};
            c.points(win, 1.7f, wp);
          }
        }
        c.restore();
      }
    }

    // Niebla en el horizonte.
    float fogTop = horizon - h * 0.18f;
    Paint fog = Paint::linear({0, fogTop}, {0, fogTop + h * 0.22f},
      {{0.47f, 0.314f, 0.408f, 0}, {0.588f, 0.373f, 0.471f, 0.6f * boost}});
    c.rect({0, fogTop, w, h * 0.22f}, fog);

    // Lluvia: un solo Path con un segmento por gota.
    Path rain;
    float wind = std::sin(t * 0.23f) * 40.0f;
    for (const auto& d : drops) {
      float y = std::fmod(d.y + t * d.v, h + 60.0f) - 20.0f;
      float x = std::fmod(d.x + wind * (y / h), w);
      if (x < 0) x += w;
      rain.moveTo(x, y);
      rain.lineTo(x - wind * 0.02f, y + d.len);
    }
    Paint rp; rp.blend = Blend::plus;
    rp.color = {0.745f, 0.843f, 1, 0.42f * boost};
    rp.strokeWidth = 1.0f; rp.strokeCap = 1; rp.strokeJoin = 1;
    c.path(rain, rp);
  }
};

