class Visual final : public Scene {
  struct Ring { float z0, rot0, sides; };
  struct Star { float x, y, z0; };
  std::vector<Ring> rings;
  std::vector<Star> stars;
  static float hash11(float p) {
    float s = std::sin(p * 12.9898f) * 43758.5453f;
    return s - std::floor(s);
  }
 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    rings.clear(); stars.clear();
    rings.reserve(90); stars.reserve(260);
    for (int i = 0; i < 90; i++) {
      float side = 6.0f;
      float h = hash11(float(i) * 1.37f + float(seed % 997) * 0.013f);
      if (h > 0.5f) side = 8.0f;
      rings.push_back({0.12f + float(i) / 90.0f * 1.9f,
        hash11(float(i) * 3.71f) * 6.2831853f, side});
    }
    for (int i = 0; i < 260; i++)
      stars.push_back({rng.unit() * 2.0f - 1.0f, rng.unit() * 2.0f - 1.0f,
        rng.unit() * 1.6f + 0.1f});
  }
  void update(const Frame& f) override { (void)f; }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = float(f.time) * f.speed;
    float fmin = std::min(w, h);
    float cx = w * 0.5f + std::sin(t * 1.3f) * 8.0f * f.intensity;
    float cy = h * 0.5f + std::cos(t * 1.1f) * 8.0f * f.intensity;
    float f0 = fmin * 0.62f;
    float boost = (0.85f + 0.35f * f.music.energy + 0.3f * f.music.bass) * f.intensity;
    float rate = (0.36f + f.music.energy * 0.55f) * (f.reducedMotion ? 0.35f : 1.0f);
    float travel = t * rate;
    Paint bg; bg.color = Color::argb(0xff04060d);
    c.rect({0, 0, w, h}, bg);

    // ── Estelas: un solo Path, 260 segmentos ──
    Path streaks;
    float streakSpan = 1.7f - 0.08f;
    for (size_t i = 0; i < stars.size(); i++) {
      const Star& s = stars[i];
      float z = std::fmod(s.z0 - travel * 1.3333f, streakSpan);
      if (z < 0.08f) z += streakSpan;
      float k1 = f0 / z;
      float k2 = f0 / (z + 0.05f * (1.0f + rate));
      streaks.moveTo(cx + s.x * k2, cy + s.y * k2);
      streaks.lineTo(cx + s.x * k1, cy + s.y * k1);
    }
    Paint sp; sp.blend = Blend::plus;
    sp.color = {0.863f, 0.914f, 1, 0.498f * boost};
    sp.strokeWidth = 1.1f; sp.strokeCap = 1; sp.strokeJoin = 1;
    c.path(streaks, sp);

    // ── Aros del túnel ──
    float ringSpan = 2.0f;
    for (size_t i = 0; i < rings.size(); i++) {
      const Ring& r = rings[i];
      float z = std::fmod(r.z0 - travel, ringSpan);
      if (z < 0.1f) z += ringSpan;
      float rad = f0 * 0.62f / z;
      if (rad > std::max(w, h) * 1.6f) continue;
      float zt = (1.75f - z) / 1.75f;
      if (zt < 0.0f) zt = 0.0f; if (zt > 1.0f) zt = 1.0f;
      float a = zt * (z * 2.2f < 1.0f ? z * 2.2f : 1.0f);
      int n = int(r.sides);
      // Nueva orientación por cada vuelta completada: derivado del tiempo, no del frame.
      float cycles = std::floor((r.z0 - travel) / ringSpan);
      float base = r.rot0 + t * 6.2831853f * (0.5f + (1.0f - z) * 0.6f)
        + hash11(cycles + float(i) * 0.5f) * 6.2831853f;
      Path ring;
      for (int sd = 0; sd <= n; sd++) {
        float ang = base + float(sd) / float(n) * 6.2831853f;
        float px = cx + std::cos(ang) * rad;
        float py = cy + std::sin(ang) * rad * 0.94f;
        if (sd == 0) ring.moveTo(px, py); else ring.lineTo(px, py);
      }
      ring.close();
      Paint p; p.blend = Blend::plus;
      if (n == 6) p.color = {0.345f, 0.780f, 0.953f, a * 0.6f * boost};
      else p.color = {0.651f, 0.545f, 1, a * 0.6f * boost};
      p.strokeWidth = 0.6f + a * 3.0f; p.strokeCap = 1; p.strokeJoin = 1;
      c.path(ring, p);
    }

    // ── Núcleo: degradado radial en vez de blur real ──
    float gr = f0 * 0.5f;
    Paint glow = Paint::radial({cx, cy}, gr,
      {{1, 1, 1, (0.45f + 0.2f * f.music.spark) * boost},
       {0.345f, 0.780f, 0.953f, 0.16f * boost}, {0, 0, 0, 0}}, {0.0f, 0.35f, 1.0f});
    glow.blend = Blend::plus;
    c.circle({cx, cy}, gr, glow);
  }
};

class Visual final : public Scene {
  struct Seg { float x1, y1, x2, y2; int level; };
  struct Spore { float x, y, speed, phase; };
  std::vector<Seg> segs[10];
  std::vector<Vec2> tips;
  std::vector<Spore> spores;
  float motion = 1.0f;
  void grow(float x, float y, float a, float len, int d, float seed, float t) {
    float sway = std::sin(seed * 0.7f + t * 0.25f) * float(9 - d) * 0.025f * motion;
    float na = a + sway;
    float x2 = x + std::cos(na) * len, y2 = y + std::sin(na) * len;
    segs[9 - d].push_back({x, y, x2, y2, 9 - d});
    if (d <= 1) {
      if (tips.size() < 256) tips.push_back({x2, y2});
      return;
    }
    float spread = 0.42f + std::sin(t * 0.4f + seed) * 0.07f;
    grow(x2, y2, na - spread, len * 0.74f, d - 1, seed * 2.0f + 1.0f, t);
    grow(x2, y2, na + spread, len * 0.74f, d - 1, seed * 2.0f + 2.0f, t);
  }
 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    spores.clear(); motion = 1.0f;
    for (int i = 0; i < 70; i++)
      spores.push_back({rng.unit(), rng.unit(), 0.3f + rng.unit() * 1.2f, rng.unit() * 6.2831853f});
  }
  void update(const Frame& f) override {
    float t = float(f.time) * f.speed;
    motion = f.reducedMotion ? 0.3f : 1.0f;
    for (int i = 0; i < 10; i++) segs[i].clear();
    tips.clear();
    grow(f.width * 0.5f, f.height * 0.94f, -1.5707963f, f.height * 0.17f, 9, 1.0f, t);
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = float(f.time) * f.speed;
    float boost = (0.8f + 0.4f * f.music.energy) * f.intensity;
    Paint bg = Paint::radial({w * 0.5f, h * 0.75f}, h * 0.9f,
      {Color::argb(0xff04231c), Color::argb(0xff021410), Color::argb(0xff000705)}, {0, 0.5f, 1.0f});
    c.rect({0, 0, w, h}, bg);
    std::vector<Vec2> sbuf; sbuf.reserve(spores.size());
    for (const auto& s : spores) {
      float y = std::fmod(s.y * h - t * s.speed * 9.0f, h);
      if (y < 0) y += h;
      sbuf.push_back({s.x * w + std::sin(t * 0.6f + s.phase) * 12.0f, y});
    }
    Paint sp; sp.blend = Blend::plus;
    sp.color = {0.435f, 1, 0.753f, 0.4f * boost};
    c.points(sbuf, 1.0f, sp);
    const uint32_t cols[10] = {0xff0b3a2e, 0xff0f5c42, 0xff14855a, 0xff1fb573, 0xff43e08f,
      0xff7bffb0, 0xffb9ffd6, 0xffe6fff1, 0xffffffff, 0xffffffff};
    for (int i = 0; i < 10; i++) {
      Path path;
      for (const auto& s : segs[i]) {
        path.moveTo(s.x1, s.y1); path.lineTo(s.x2, s.y2);
      }
      Paint p; p.blend = Blend::plus;
      Color cc = Color::argb(cols[i]);
      p.color = {cc.r, cc.g, cc.b, 0.85f * boost};
      p.strokeWidth = std::max(0.6f, float(9 - i) * 0.52f);
      c.path(path, p);
    }
    Paint tp; tp.blend = Blend::plus;
    tp.color = {0.788f, 1, 0.902f, (0.45f + 0.45f * std::abs(std::sin(t * 2.0f))) * boost};
    c.points(tips, 1.6f, tp);
  }
};

class Visual final : public Scene {
  float road=0;
 public:
  void reset(uint32_t) override {road=0;}
  void update(const Frame& f) override {road+=float(f.delta)*f.speed*.18f;}
  void render(const Frame& f, Canvas& c) const override {
    float w=f.width,h=f.height,horizon=h*.61f;
    c.rect({0,0,w,h},Paint::linear({0,0},{0,h},
      {Color::argb(0xff050722),Color::argb(0xff391b58),Color::argb(0xffee487b),Color::argb(0xff070614)},{0,.38f,.61f,.85f}));
    float radius=w*.27f; Vec2 sun={w*.5f,h*.39f};
    Path cut;cut.fillRule=FillRule::evenOdd;cut.circle(sun,radius);
    for(int i=0;i<8;i++) {float y=sun.y+radius*(-.1f+i*.14f);cut.rect({sun.x-radius,y,radius*2,2+i*1.2f});}
    c.save();c.clip(cut);
    Path within;within.circle(sun,radius);c.clip(within);
    c.rect({sun.x-radius,sun.y-radius,radius*2,radius*2},Paint::linear({0,sun.y-radius},{0,sun.y+radius},
      {Color::argb(0xfffff39d),Color::argb(0xffff7770),Color::argb(0xffff2cbd)}));c.restore();
    Paint mountain;mountain.color=Color::argb(0xff0a0b27);
    Path ridge;ridge.moveTo(0,horizon).lineTo(0,horizon-25).lineTo(w*.13f,horizon-95)
      .lineTo(w*.27f,horizon-45).lineTo(w*.4f,horizon-100).lineTo(w*.6f,horizon-22)
      .lineTo(w*.83f,horizon-116).lineTo(w,horizon-41).lineTo(w,horizon).close();c.path(ridge,mountain);
    Paint ground;ground.color=Color::argb(0xff080715);c.rect({0,horizon,w,h-horizon},ground);
    c.saveLayer(.65f+f.music.bass*.25f,Blend::screen);
    Paint grid;grid.color=Color{.55f,.2f,1,1};grid.strokeWidth=1;
    for(int i=-10;i<=10;i++){Path p;p.moveTo(w*.5f+i*5,horizon).lineTo(w*.5f+i*w*.22f,h);c.path(p,grid);}
    for(int i=0;i<18;i++){float t=std::fmod(i/18.f+road,1.f);float y=horizon+t*t*(h-horizon);Path p;p.moveTo(0,y).lineTo(w,y);c.path(p,grid);}
    c.restore();
    Paint glow=Paint::radial({w*.5f,horizon},w*.6f,{Color{1,.12f,.48f,.22f},Color{1,0,.4f,0}});glow.blend=Blend::screen;
    c.rect({0,horizon-w*.2f,w,w*.4f},glow);
  }
};

class Visual final : public Scene {
  static constexpr int nb = 12;
  struct Blob { float ang, spd, rad; };
  std::vector<Blob> blobs;
 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    blobs.clear(); blobs.reserve(nb);
    for (int i = 0; i < nb; i++) {
      Blob b;
      b.ang = rng.unit() * 6.2831853f;
      b.spd = 0.12f + rng.unit() * 0.3f;
      b.rad = 0.06f + rng.unit() * 0.12f;
      blobs.push_back(b);
    }
  }
  void update(const Frame& f) override { (void)f; }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = float(f.time) * f.speed;
    float time = t * 6.2831853f;
    float pull = 1.0f + f.music.energy * 0.9f + f.music.bass * 0.5f;
    std::vector<float> u;
    u.reserve(40);
    u.push_back(time);
    u.push_back(pull);
    for (int i = 0; i < nb; i++) {
      const Blob& b = blobs[i];
      float a = b.ang + time * b.spd * (i % 2 == 0 ? 1.0f : -1.0f);
      float rr = b.rad * (1.0f + 0.28f * std::sin(time * 0.6f + float(i)));
      u.push_back(w * (0.5f + std::cos(a) * (0.26f + rr)));
      u.push_back(h * (0.5f + std::sin(a * 1.27f + float(i)) * (0.3f + rr)));
      u.push_back(rr * (1.0f + (pull - 1.0f) * 0.22f) * std::min(w, h));
    }
    c.material("ink", {0, 0, w, h}, u);
  }
};

